import sys


def greet(name):
    if name == "":
        return "Hello, stranger!"
    return f"Hello, {name}!"


def main():
    if len(sys.argv) < 2 or sys.argv[1] == "":
        print("usage: greet.py NAME", file=sys.stderr)
        sys.exit(2)
    print(greet(sys.argv[1]))


if __name__ == "__main__":
    main()
